  `unit` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pcs',
  `is_quantity_based` tinyint(1) NOT NULL DEFAULT 1,
  `stock` int(10) unsigned DEFAULT NULL,
